import numpy as np,json
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
s=json.load(open('/app/output/spec.json'))
names=s['proprio']['joints']; axes=np.array(s['proprio']['axis']); pts=np.array(s['proprio']['position_m'])
links=s['links']['names']; parents=s['links']['parent']
# Every child link after pelvis corresponds to one proprio joint.
linkj={l:i-1 for i,l in enumerate(links) if i}
parentj=[linkj.get(parents[i+1],-1) for i in range(69)]
def transforms(q):
    tr=[]
    for i in range(69):
        R=Rotation.from_rotvec(axes[i]/np.linalg.norm(axes[i])*q[i]).as_matrix(); T=np.eye(4);T[:3,:3]=R;T[:3,3]=pts[i]-R@pts[i]
        tr.append((tr[parentj[i]] if parentj[i]>=0 else np.eye(4))@T)
    return tr
cam=s['cameras']['room_camera']; cp=np.array(cam['pose']['position_m']); cr=np.array(cam['pose']['right']); cu=np.array(cam['pose']['up']); cf=np.array(cam['pose']['forward']);f=128/np.tan(np.deg2rad(22.5))
def project(p):
    a=np.array(p)-cp
    return np.array([127.5+f*(a@cr)/(a@cf),127.5-f*(a@cu)/(a@cf)])
def unproject(u,v,z):
    ray=cf+cr*(u-127.5)/f-cu*(v-127.5)/f
    return cp+ray*((z-cp[2])/ray[2])
if __name__=='__main__':
    for z in [.8,.9,1.0]:
        print(z, 'head',unproject(139,161,z),'handle',unproject(166,139,z),'cup',unproject(102,78,z+.2)))
